import Tonyu from "../runtime/TonyuRuntime.js";
import WebSite from "../runtime/WebSite.js";
import miniJSLoader from "../lib/miniJSLoader.js";
miniJSLoader.load(WebSite.compiledKernel);// It takes several times...
export default {
    isKernel: name=>{
        if (!Tonyu.classes.kernel) {
            return false;
        }
        return Tonyu.classes.kernel[name];
    }
};